create table public."online_data_chat_message_parts" (
 online_project_id uuid not null references public.online_project_data(project_id),
 "id" text not null,
 "project_id" text not null,
 "message_id" text not null,
 "ordinal" bigint not null,
 "part_kind" text not null,
 "text_content" text,
 "structured_json" text,
 "artifact_id" text,
 primary key(online_project_id,"id"),
 check(structured_json IS NULL OR (structured_json IS JSON))
);
alter table public."online_data_chat_message_parts" enable row level security;
revoke all on public."online_data_chat_message_parts" from public,anon,authenticated;
grant select on public."online_data_chat_message_parts" to authenticated;
create policy owner_select on public."online_data_chat_message_parts" for select to authenticated using(exists(select 1 from public.online_projects p where p.id=online_project_id and p.owner_id=(select auth.uid())));

create table public."online_data_chat_messages" (
 online_project_id uuid not null references public.online_project_data(project_id),
 "id" text not null,
 "project_id" text not null,
 "thread_id" text not null,
 "parent_message_id" text,
 "role" text not null,
 "actor_id" text,
 "state" text,
 "agent_id" text,
 "requested_model" text,
 "resolved_model" text,
 "reasoning_level" text,
 "service_tier" text,
 "runtime_version" text,
 "task_kind" text,
 "output_contract" text,
 "prompt_contract_version" text,
 "request_manifest_json" text,
 "request_manifest_hash" text,
 "request_artifact_id" text,
 "response_artifact_id" text,
 "events_artifact_id" text,
 "output_validation_state" text,
 "usage_json" text,
 "error_json" text,
 "started_at" text,
 "completed_at" text,
 "created_at" text not null,
 primary key(online_project_id,"id"),
 check(role IN ('user', 'assistant', 'system')),
 check(request_manifest_json IS NULL OR (request_manifest_json IS JSON)),
 check(usage_json IS NULL OR (usage_json IS JSON)),
 check(error_json IS NULL OR (error_json IS JSON))
);
alter table public."online_data_chat_messages" enable row level security;
revoke all on public."online_data_chat_messages" from public,anon,authenticated;
grant select on public."online_data_chat_messages" to authenticated;
create policy owner_select on public."online_data_chat_messages" for select to authenticated using(exists(select 1 from public.online_projects p where p.id=online_project_id and p.owner_id=(select auth.uid())));

create table public."online_data_chat_threads" (
 online_project_id uuid not null references public.online_project_data(project_id),
 "id" text not null,
 "project_id" text not null,
 "title" text,
 "scope_kind" text,
 "scope_id" text,
 "created_by_actor_id" text not null,
 "created_at" text not null,
 primary key(online_project_id,"id")
