create table public."online_data_reading_annotations" (
 online_project_id uuid not null references public.online_project_data(project_id),
 "id" text not null,
 "project_id" text not null,
 "document_node_id" text not null,
 "source_version_id" text not null,
 "source_content_hash" text not null,
 "codepoint_from" bigint not null,
 "codepoint_to" bigint not null,
 "quote" text not null,
 "reading" text not null default '',
 "gloss" text not null default '',
 "reading_order" bigint,
 "citation_json" text,
 "content_hash" text not null,
 "lock_version" bigint not null default 1,
 "created_by_actor_id" text not null,
 "updated_by_actor_id" text not null,
 "created_at" text not null,
 "updated_at" text not null,
 "archived_at" text,
 primary key(online_project_id,"id"),
 check(length(source_content_hash) = 64 AND source_content_hash !~ '[^0-9a-f]'),
 check(codepoint_from >= 0),
 check(codepoint_to > codepoint_from AND codepoint_to <= 20000000 AND codepoint_to - codepoint_from <= 100),
 check(length(quote) = codepoint_to - codepoint_from AND length(trim(quote)) > 0),
 check(length(reading) <= 100),
 check(length(gloss) <= 2000),
 check(reading_order IS NULL OR reading_order BETWEEN 1 AND 1000000),
 check(citation_json IS NULL OR (
    length(citation_json) <= 40000 AND (citation_json IS JSON)
    AND COALESCE(jsonb_typeof(citation_json::jsonb) = 'object'
      AND jsonb_typeof(citation_json::jsonb->'source') = 'string'
      AND jsonb_typeof(citation_json::jsonb->'sourceLabel') = 'string'
      AND jsonb_typeof(citation_json::jsonb->'entryId') = 'string'
      AND jsonb_typeof(citation_json::jsonb->'headword') = 'string'
      AND jsonb_typeof(citation_json::jsonb->'reading') IN ('string', 'null')
      AND jsonb_typeof(citation_json::jsonb->'sense') = 'string'
      AND jsonb_typeof(citation_json::jsonb->'sourceUrl') = 'string'
      AND jsonb_typeof(citation_json::jsonb->'license') = 'string'
      AND jsonb_typeof(citation_json::jsonb->'licenseUrl') IN ('string', 'null')
      AND jsonb_typeof(citation_json::jsonb->'attribution') = 'string', false)
  )),
 check(length(content_hash) = 64 AND content_hash !~ '[^0-9a-f]'),
 check(lock_version >= 1),
 check(length(trim(reading)) > 0 OR length(trim(gloss)) > 0 OR reading_order IS NOT NULL OR citation_json IS NOT NULL)
);
