create function private.online_data_validate_row(p_table text,p_row jsonb,p_key jsonb) returns void
language plpgsql security invoker set search_path='' as $$
declare v_catalog jsonb:=private.online_data_catalog()->p_table; v_col text; v_type text;
begin
 if v_catalog is null or jsonb_typeof(p_key)<>'object' or
   (select array_agg(k order by k) from jsonb_object_keys(p_key) k) is distinct from
   (select array_agg(k order by k) from jsonb_array_elements_text(v_catalog->'key') k) then raise exception 'ONLINE_DATA_INVALID_KEY'; end if;
 if p_row is null then return; end if;
 if jsonb_typeof(p_row)<>'object' or
   (select array_agg(k order by k) from jsonb_object_keys(p_row) k) is distinct from
   (select array_agg(k order by k) from jsonb_array_elements_text(v_catalog->'columns') k) then raise exception 'ONLINE_DATA_INVALID_COLUMNS'; end if;
 if not p_row @> p_key or exists(select 1 from jsonb_each(p_key) where value='null'::jsonb) then raise exception 'ONLINE_DATA_INVALID_KEY'; end if;
 for v_col,v_type in select key,value from jsonb_each_text(v_catalog->'types') loop
  if p_row->v_col='null'::jsonb then continue; end if;
  if (v_type='TEXT' and jsonb_typeof(p_row->v_col)<>'string') or
     (v_type in ('INTEGER','REAL') and jsonb_typeof(p_row->v_col)<>'number') or
     (v_type='INTEGER' and (p_row->>v_col)::numeric<>trunc((p_row->>v_col)::numeric)) then raise exception 'ONLINE_DATA_INVALID_TYPE: %',v_col; end if;
 end loop;
end $$;
revoke all on function private.online_data_validate_row(text,jsonb,jsonb) from public,anon,authenticated;

create function private.get_online_project_data(p_project_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_head public.online_project_data; v_tables jsonb:='{}'; v_name text; v_rows jsonb;
begin
 perform private.online_data_assert_owner(p_project_id);
 -- SHARE lock gives a consistent snapshot across the table reads and excludes commit.
 perform 1 from public.online_projects where id=p_project_id for share;
 select * into v_head from public.online_project_data where project_id=p_project_id for share;
 for v_name in select jsonb_object_keys(private.online_data_catalog()) loop
  execute format('select coalesce(jsonb_agg(to_jsonb(t)-''online_project_id''),''[]''::jsonb) from public.%I t where online_project_id=$1','online_data_'||v_name) into v_rows using p_project_id;
  v_tables:=v_tables||jsonb_build_object(v_name,v_rows);
 end loop;
 return jsonb_build_object('project_id',p_project_id,'data_project_id',v_head.data_project_id,'schema_version',coalesce(v_head.schema_version,10),'revision',coalesce(v_head.revision,0),'updated_at',coalesce(v_head.updated_at,(select updated_at from public.online_projects where id=p_project_id)),'tables',v_tables);
end $$;

create function private.commit_online_project_data(p_project_id uuid,p_expected_revision bigint,p_mutation_id uuid,p_schema_version integer,p_changes jsonb,p_legacy_lease_id uuid default null,p_legacy_fence bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare
 v_head public.online_project_data; v_receipt private.online_project_commits; v_hash text; v_legacy public.online_project_workspaces;
 v_change jsonb; v_table text; v_key jsonb; v_before jsonb; v_after jsonb; v_current jsonb;
 v_catalog jsonb:=private.online_data_catalog(); v_info jsonb; v_predicate text; v_assignments text;
 v_seen jsonb:='[]'; v_identity jsonb; v_journal jsonb:='[]'; v_internal text; v_names text; v_values text;
 v_asset record; v_object jsonb;
begin
 perform private.online_data_assert_owner(p_project_id);
 if p_expected_revision is null or p_expected_revision<0 or p_mutation_id is null or p_schema_version is distinct from 10 or jsonb_typeof(p_changes) is distinct from 'array' or jsonb_array_length(p_changes)>20000 or octet_length(p_changes::text)>16777216 then raise exception 'ONLINE_DATA_INVALID_REQUEST'; end if;
 -- Legacy writers lock workspace before project; keep the same order during conversion.
 if p_expected_revision=0 then select * into v_legacy from public.online_project_workspaces where project_id=p_project_id for update; end if;
 perform 1 from public.online_projects where id=p_project_id for update;
 v_hash:=encode(sha256(convert_to(jsonb_build_object('expected_revision',p_expected_revision,'schema_version',p_schema_version,'changes',p_changes,'legacy_lease_id',p_legacy_lease_id,'legacy_fence',p_legacy_fence)::text,'UTF8')),'hex');
 select * into v_receipt from private.online_project_commits where project_id=p_project_id and mutation_id=p_mutation_id;
 if found then
  if v_receipt.request_hash<>v_hash then raise exception 'ONLINE_DATA_MUTATION_CONFLICT' using errcode='23505'; end if;
  return jsonb_build_object('revision',v_receipt.revision,'updated_at',v_receipt.updated_at);
 end if;
 insert into public.online_project_data(project_id) values(p_project_id) on conflict do nothing;
 select * into strict v_head from public.online_project_data where project_id=p_project_id for update;
 if v_head.revision<>p_expected_revision then raise exception 'ONLINE_DATA_REVISION_CONFLICT' using errcode='40001'; end if;
 if v_head.revision=0 and v_legacy.object_path is not null and (p_legacy_lease_id is null or p_legacy_fence is null or v_legacy.lease_id is distinct from p_legacy_lease_id or v_legacy.fence is distinct from p_legacy_fence or v_legacy.lease_expires_at is null or v_legacy.lease_expires_at<=clock_timestamp()) then raise exception 'ONLINE_DATA_LEGACY_LEASE_LOST'; end if;
 v_internal:=v_head.data_project_id;
 if v_internal is null then
  select value->'after'->>'id' into v_internal from jsonb_array_elements(p_changes)
   where value->>'table'='core_projects' and value->'before'='null'::jsonb and jsonb_typeof(value->'after')='object';
  if v_internal is null or length(v_internal)=0 or length(v_internal)>200 then raise exception 'ONLINE_DATA_PROJECT_REQUIRED'; end if;
 end if;
 set constraints all deferred;
 for v_change in select value from jsonb_array_elements(p_changes) loop
  if jsonb_typeof(v_change)<>'object' or (select array_agg(k order by k) from jsonb_object_keys(v_change) k) is distinct from array['after','before','key','table'] then raise exception 'ONLINE_DATA_INVALID_CHANGE'; end if;
  v_table:=v_change->>'table';v_key:=v_change->'key';v_before:=nullif(v_change->'before','null'::jsonb);v_after:=nullif(v_change->'after','null'::jsonb);v_info:=v_catalog->v_table;
  if v_info is null or (v_before is null and v_after is null) then raise exception 'ONLINE_DATA_INVALID_TABLE_OR_CHANGE'; end if;
  perform private.online_data_validate_row(v_table,v_before,v_key);perform private.online_data_validate_row(v_table,v_after,v_key);
  v_identity:=jsonb_build_object('table',v_table,'key',v_key);
  if v_seen @> jsonb_build_array(v_identity) then raise exception 'ONLINE_DATA_DUPLICATE_CHANGE'; end if;
  v_seen:=v_seen||jsonb_build_array(v_identity);
  if (v_after ? 'project_id' and v_after->>'project_id' is distinct from v_internal) or
     (v_before ? 'project_id' and v_before->>'project_id' is distinct from v_internal) or
     (v_table='core_projects' and (coalesce(v_after,v_before)->>'id' is distinct from v_internal or v_after is null)) then raise exception 'ONLINE_DATA_PROJECT_MISMATCH'; end if;
  select string_agg(format('t.%I=(jsonb_populate_record(null::public.%I,$2)).%I',k,'online_data_'||v_table,k),' and ') into v_predicate from jsonb_array_elements_text(v_info->'key') k;
  execute format('select to_jsonb(t)-''online_project_id'' from public.%I t where t.online_project_id=$1 and %s for update','online_data_'||v_table,v_predicate) into v_current using p_project_id,v_key;
  if v_current is distinct from v_before then raise exception 'ONLINE_DATA_ROW_CONFLICT' using errcode='40001'; end if;
  if v_after is null then
   execute format('delete from public.%I t where t.online_project_id=$1 and %s','online_data_'||v_table,v_predicate) using p_project_id,v_key;
  elsif v_before is null then
   select string_agg(format('%I',k),','),string_agg(format('r.%I',k),',') into v_names,v_values from jsonb_array_elements_text(v_info->'columns') k;
   execute format('insert into public.%I (online_project_id,%s) select $1,%s from jsonb_populate_record(null::public.%I,$2) r','online_data_'||v_table,v_names,v_values,'online_data_'||v_table) using p_project_id,v_after;
  else
   select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$3)).%I',k,'online_data_'||v_table,k),',') into v_assignments from jsonb_array_elements_text(v_info->'columns') k where v_before->k is distinct from v_after->k;
   if v_assignments is not null then execute format('update public.%I t set %s where t.online_project_id=$1 and %s','online_data_'||v_table,v_assignments,v_predicate) using p_project_id,v_key,v_after; end if;
  end if;
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('table',v_table,'key',v_key,'after',v_after));
 end loop;
 -- Completed immutable objects must exist before canonical attachment metadata.
 -- Check descriptor changes too: changing an asset hash cannot bypass this gate.
 for v_asset in
  select distinct a.id,a.sha256,a.byte_size from public.online_data_src_asset_locations l
  join public.online_data_src_assets a on a.online_project_id=l.online_project_id and a.id=l.asset_id
  where l.online_project_id=p_project_id and exists(select 1 from jsonb_array_elements(p_changes) c
   where (c->>'table'='src_asset_locations' and c->'after'->>'id'=l.id)
      or (c->>'table'='src_assets' and c->'after'->>'id'=a.id))
 loop
  if v_asset.sha256 is null or v_asset.sha256 !~ '^[0-9a-f]{64}$' or v_asset.byte_size is null or v_asset.byte_size not between 1 and 52428800 then raise exception 'ONLINE_DATA_ASSET_INVALID'; end if;
  select metadata into v_object from storage.objects where bucket_id='online-project-assets' and name=auth.uid()::text||'/'||p_project_id::text||'/'||v_asset.sha256;
  if not found then raise exception 'ONLINE_DATA_ASSET_MISSING'; end if;
  if (case when v_object->>'size' ~ '^[0-9]{1,16}$' then (v_object->>'size')::bigint else null end) is distinct from v_asset.byte_size then raise exception 'ONLINE_DATA_ASSET_INVALID'; end if;
 end loop;
 if (select count(*) from public.online_data_core_projects where online_project_id=p_project_id)<>1 or
    (select count(*) from public.online_data_document_nodes where online_project_id=p_project_id and is_master=1 and archived_at is null)<>1 then raise exception 'ONLINE_DATA_MASTER_REQUIRED'; end if;
 -- Run all deferred FKs, uniqueness and ported SQLite validation before acknowledging.
 set constraints all immediate;
 update public.online_project_data set data_project_id=v_internal,revision=revision+1,updated_at=clock_timestamp() where project_id=p_project_id returning * into v_head;
 insert into private.online_project_commits values(p_project_id,v_head.revision,p_mutation_id,v_hash,v_journal,v_head.updated_at);
 update public.online_projects set updated_at=v_head.updated_at where id=p_project_id;
 return jsonb_build_object('revision',v_head.revision,'updated_at',v_head.updated_at);
end $$;

create function private.get_online_project_changes(p_project_id uuid,p_after_revision bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_head public.online_project_data;v_commits jsonb;
begin
 perform private.online_data_assert_owner(p_project_id);
 if p_after_revision is null or p_after_revision<0 then raise exception 'ONLINE_DATA_INVALID_REVISION'; end if;
 perform 1 from public.online_projects where id=p_project_id for share;
 select * into v_head from public.online_project_data where project_id=p_project_id for share;
 if p_after_revision>coalesce(v_head.revision,0) then raise exception 'ONLINE_DATA_INVALID_REVISION'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('revision',revision,'mutation_id',mutation_id,'changes',changes) order by revision),'[]') into v_commits
  from private.online_project_commits where project_id=p_project_id and revision>p_after_revision;
 return jsonb_build_object('revision',coalesce(v_head.revision,0),'updated_at',coalesce(v_head.updated_at,(select updated_at from public.online_projects where id=p_project_id)),'commits',v_commits);
end $$;


revoke all on function private.get_online_project_data(uuid) from public,anon,authenticated;
grant execute on function private.get_online_project_data(uuid) to authenticated;
create function public.get_online_project_data(p_project_id uuid) returns jsonb language sql security invoker set search_path='' as $$ select private.get_online_project_data(p_project_id) $$;
revoke all on function public.get_online_project_data(uuid) from public,anon,authenticated;
grant execute on function public.get_online_project_data(uuid) to authenticated;

revoke all on function private.commit_online_project_data(uuid,bigint,uuid,integer,jsonb,uuid,bigint) from public,anon,authenticated;
grant execute on function private.commit_online_project_data(uuid,bigint,uuid,integer,jsonb,uuid,bigint) to authenticated;
create function public.commit_online_project_data(p_project_id uuid,p_expected_revision bigint,p_mutation_id uuid,p_schema_version integer,p_changes jsonb,p_legacy_lease_id uuid default null,p_legacy_fence bigint default null) returns jsonb language sql security invoker set search_path='' as $$ select private.commit_online_project_data(p_project_id,p_expected_revision,p_mutation_id,p_schema_version,p_changes,p_legacy_lease_id,p_legacy_fence) $$;
revoke all on function public.commit_online_project_data(uuid,bigint,uuid,integer,jsonb,uuid,bigint) from public,anon,authenticated;
grant execute on function public.commit_online_project_data(uuid,bigint,uuid,integer,jsonb,uuid,bigint) to authenticated;

revoke all on function private.get_online_project_changes(uuid,bigint) from public,anon,authenticated;
grant execute on function private.get_online_project_changes(uuid,bigint) to authenticated;
create function public.get_online_project_changes(p_project_id uuid,p_after_revision bigint) returns jsonb language sql security invoker set search_path='' as $$ select private.get_online_project_changes(p_project_id,p_after_revision) $$;
revoke all on function public.get_online_project_changes(uuid,bigint) from public,anon,authenticated;
grant execute on function public.get_online_project_changes(uuid,bigint) to authenticated;


-- Only the tiny revision head enters Realtime. Content rows are read through RPCs.
do $$ begin
 if exists(select 1 from pg_publication where pubname='supabase_realtime') and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='online_project_data') then
 alter publication supabase_realtime add table public.online_project_data; end if;
end $$;

-- Preserve old checkpoints for recovery, but old clients cannot overwrite canonical data.
create function private.online_data_block_legacy_write() returns trigger language plpgsql security invoker set search_path='' as $$ begin
 perform 1 from public.online_projects where id=NEW.project_id for update;
 if (NEW.revision is distinct from OLD.revision or NEW.object_path is distinct from OLD.object_path) and exists(select 1 from public.online_project_data where project_id=NEW.project_id and revision>0) then raise exception 'ONLINE_DATA_MIGRATED'; end if;
 return NEW; end $$;
revoke all on function private.online_data_block_legacy_write() from public,anon,authenticated;
create trigger online_data_block_legacy_write before update on public.online_project_workspaces for each row execute function private.online_data_block_legacy_write();

insert into storage.buckets(id,name,public,file_size_limit) values('online-project-assets','online-project-assets',false,52428800) on conflict(id) do nothing;
do $$ begin if not exists(select 1 from storage.buckets where id='online-project-assets' and not public and file_size_limit=52428800) then raise exception 'ONLINE_ASSET_BUCKET_CONFIGURATION'; end if; end $$;
create function private.online_asset_owner(p_name text) returns boolean language plpgsql stable security definer set search_path='' as $$ begin
 if auth.uid() is null or p_name !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{64}$' then return false; end if;
 return split_part(p_name,'/',1)=auth.uid()::text and exists(select 1 from public.online_projects where id=split_part(p_name,'/',2)::uuid and owner_id=auth.uid());
end $$;
revoke all on function private.online_asset_owner(text) from public,anon,authenticated;
grant execute on function private.online_asset_owner(text) to authenticated;
create policy online_assets_owner_select on storage.objects for select to authenticated using(bucket_id='online-project-assets' and private.online_asset_owner(name));
create policy online_assets_owner_insert on storage.objects for insert to authenticated with check(bucket_id='online-project-assets' and private.online_asset_owner(name));

